17: 
18: /// Framing delimiter sentinel byte separating consecutive records (`0xFF` / `255` decimal).
19: pub const RECORD_DELIMITER: u8 = 0xFF;
20: 
21: /// A zero-allocation borrowed view of a raw DJI `.txt` flight telemetry record envelope.
22: ///
23: /// Encapsulates the record type identifier and borrowed payload slice directly
24: /// referencing the memory-mapped or buffered flight log byte stream.
25: #[derive(Debug, Clone, PartialEq, Eq)]
26: pub struct RawRecordEnvelope<'a> {
27:     /// Numerical record type identifier (e.g. 1 for OSD, 2 for Home, 56 for KeyStorage).
28:     pub record_type: u8,
29:     /// Borrowed raw payload slice directly referencing the stream buffer.
30:     ///
31:     /// - For v1–v6: unencrypted plaintext telemetry payload.
32:     /// - For v7–v12: raw scrambled payload starting with the seed byte (`payload[0]`).
33:     /// - For v13–v14: raw envelope payload (or plaintext bypass for FeaturePoint 8).
34:     pub payload: &'a [u8],
35: }
36: 
37: impl<'a> RawRecordEnvelope<'a> {
38:     /// Constructs a new `RawRecordEnvelope` from borrowed fields.
39:     #[inline]
40:     pub const fn new(record_type: u8, payload: &'a [u8]) -> Self {
41:         Self {
42:             record_type,
43:             payload,
44:         }
45:     }
46: 
47:     /// Parses a single record envelope from the beginning of `input`.
48:     ///
49:     /// # Protocol Wire Format
50:     /// - Byte 0: `record_type` (`u8`)
51:     /// - Bytes 1..=W: `length` (`u8` if `record_len_width == 1`, `u16_le` if `record_len_width == 2`)
52:     /// - Bytes (1+W)..((1+W)+L): `payload` (`L` bytes)
53:     /// - Byte (1+W)+L: Delimiter byte (must equal `0xFF`)
54:     ///
55:     /// Returns `Ok((envelope, total_consumed_bytes))`.
56:     ///
57:     /// # Errors
58:     /// - [`FlightReaderError::UnexpectedEof`] if `input.len()` cannot hold the record header.
59:     /// - [`FlightReaderError::TruncatedRecord`] if `input.len()` is less than the full wire size.
60:     /// - [`FlightReaderError::InvalidRecordDelimiter`] if the byte following the payload is not `0xFF`.
61:     /// - [`FlightReaderError::UnsupportedVersion`] if `record_len_width` is not 1 or 2.
62:     pub fn parse(input: &'a [u8], record_len_width: usize) -> Result<(Self, usize)> {
63:         let header_size = 1 + record_len_width;
64:         if input.len() < header_size {
65:             return Err(FlightReaderError::UnexpectedEof);
66:         }
67: 
68:         let record_type = input[0];
69:         let payload_len = match record_len_width {
70:             1 => input[1] as usize,
71:             2 => LittleEndian::read_u16(&input[1..3]) as usize,
72:             other => {
73:                 return Err(FlightReaderError::UnsupportedVersion {
74:                     version: other as u8,
75:                 });
76:             }
77:         };
78: 
79:         let total_len = header_size + payload_len + 1;
80:         if input.len() < total_len {
81:             return Err(FlightReaderError::TruncatedRecord {
82:                 expected: total_len,
83:                 available: input.len(),
84:             });
85:         }
86: 
87:         let delimiter = input[header_size + payload_len];
88:         if delimiter != RECORD_DELIMITER {
89:             return Err(FlightReaderError::InvalidRecordDelimiter { found: delimiter });
90:         }
91: 
92:         let payload = &input[header_size..header_size + payload_len];
93:         Ok((Self { record_type, payload }, total_len))
94:     }
95: 
96:     /// De-scrambles or passes through the record payload into a caller-provided destination slice.
97:     ///
98:     /// # Behavior by Version
99:     /// - **v1–v6** (`ScrambleType::None`): Plaintext copy into `out_buf`.
100:     /// - **v7–v12** (`ScrambleType::Xor`): De-scrambles `payload[1..]` into `out_buf` using
101:     ///   ECMA-182 CRC64 keystream derived from `(record_type, payload[0])`.
102:     /// - **v13–v14** (`ScrambleType::Aes`): Yields raw envelope payload into `out_buf`
103:     ///   (plaintext bypass for FeaturePoint 8: `KeyStorage` 56, `FlightRecordRecover` 50).
104:     ///
105:     /// # Errors
106:     /// - [`FlightReaderError::BufferOverflow`] if `out_buf` capacity is insufficient.
107:     /// - [`FlightReaderError::PayloadTooShort`] if XOR scrambled payload length is `< 2` (requires seed + data).
108:     /// - [`FlightReaderError::UnsupportedVersion`] if `version` is not supported.
109:     pub fn decode_into<'b>(&self, version: u8, out_buf: &'b mut [u8]) -> Result<&'b [u8]> {
110:         let caps = classify_version(version)?;
111:         match caps.scramble_type {
112:             ScrambleType::None => {
113:                 if out_buf.len() < self.payload.len() {
114:                     return Err(FlightReaderError::BufferOverflow {
115:                         required: self.payload.len(),
116:                         capacity: out_buf.len(),
117:                     });
118:                 }
119:                 out_buf[..self.payload.len()].copy_from_slice(self.payload);
120:                 Ok(&out_buf[..self.payload.len()])
121:             }
122:             ScrambleType::Xor => {
123:                 if self.payload.is_empty() {
124:                     return Ok(&[]);
125:                 }
126:                 if self.payload.len() < 2 {
127:                     return Err(FlightReaderError::PayloadTooShort {
128:                         minimum: 2,
129:                         available: self.payload.len(),
130:                     });
131:                 }
132:                 let plaintext_len = self.payload.len() - 1;
133:                 if out_buf.len() < plaintext_len {
134:                     return Err(FlightReaderError::BufferOverflow {
135:                         required: plaintext_len,
136:                         capacity: out_buf.len(),
137:                     });
138:                 }
139:                 let seed = self.payload[0];
140:                 let key = crate::crypto::derive_key(self.record_type, seed);
141:                 xor::descramble_slice(&self.payload[1..], &mut out_buf[..plaintext_len], key)?;
142:                 Ok(&out_buf[..plaintext_len])
143:             }
144:             ScrambleType::Aes => {
145:                 if out_buf.len() < self.payload.len() {
146:                     return Err(FlightReaderError::BufferOverflow {
147:                         required: self.payload.len(),
148:                         capacity: out_buf.len(),
149:                     });
150:                 }
